```section
<section id="calculator" aria-labelledby="calculator-title">
<style>
#calculator .calc-intro{margin-bottom:24px;color:var(--j2-muted)}
#calculator .calc-card{display:grid;grid-template-columns:1fr;gap:24px;padding:20px}
#calculator .calc-fields{display:grid;grid-template-columns:1fr;gap:16px;min-width:0}
#calculator .calc-field{min-width:0}
#calculator .calc-field label{margin-bottom:6px}
#calculator .calc-hint{margin:6px 0 0;font-size:.9rem;color:var(--j2-muted)}
#calculator .calc-result{min-width:0;padding:20px;background:var(--j2-background);border:2px solid var(--j2-secondary);border-radius:var(--j2-radius)}
#calculator .calc-result h3{margin:0 0 12px}
#calculator .calc-lines{list-style:none;margin:0 0 16px;padding:0;display:grid;gap:8px}
#calculator .calc-lines li{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px 16px;margin:0;font-weight:600}
#calculator .calc-total-line{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px;margin:0 0 12px;padding-top:12px;border-top:2px solid var(--j2-secondary);font-family:var(--j2-font-heading);font-size:1.25rem;font-weight:700;color:var(--j2-secondary)}
#calculator .calc-total-line output{display:inline-block}
#calculator .calc-status{margin:0 0 16px;font-weight:600}
#calculator .calc-error{margin:0 0 12px}
#calculator .calc-cta{width:100%}
@media (min-width:768px){
#calculator .calc-card{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}
#calculator .calc-cta{width:auto}
}
</style>
<h2 id="calculator-title">Fee calculator</h2>
<p class="calc-intro">Pick your ticket type, the number of participants and any meal passes to see your total. Early-bird takes 10% off entry fees only, never meal passes.</p>
<div class="calc-card j2-card">
<div class="calc-fields" role="group" aria-labelledby="calculator-title">
<div class="calc-field">
<label for="calc-ticket">Ticket type</label>
<select id="calc-ticket" name="calc-ticket">
<option value="Student">Student</option>
<option value="Professional">Professional</option>
</select>
</div>
<div class="calc-field">
<label for="calc-people">Number of participants (1 to 4)</label>
<input id="calc-people" name="calc-people" type="number" inputmode="numeric" min="1" max="4" step="1" value="1" aria-describedby="calc-error">
</div>
<div class="calc-field">
<label for="calc-meals">Number of meal passes (optional)</label>
<input id="calc-meals" name="calc-meals" type="number" inputmode="numeric" min="0" step="1" value="0" aria-describedby="calc-error">
</div>
<div class="calc-field">
<label for="calc-date">Registration date</label>
<input id="calc-date" name="calc-date" type="date" aria-describedby="calc-date-hint">
<p class="calc-hint" id="calc-date-hint">Defaults to today. Early-bird applies to registrations up to 15 February 2027.</p>
</div>
</div>
<div class="calc-result" aria-live="polite">
<h3>Your total</h3>
<ul class="calc-lines">
<li><span>Entry fees</span><span id="calc-entry">Rs 0</span></li>
<li><span>Early-bird discount (entry fees only)</span><span id="calc-discount">Rs 0</span></li>
<li><span>Meal passes</span><span id="calc-mealcost">Rs 0</span></li>
</ul>
<p class="calc-total-line"><span>Total Rs</span> <output id="calc-total" for="calc-ticket calc-people calc-meals calc-date">0</output></p>
<p class="calc-status" id="calc-status"></p>
<p class="calc-error" id="calc-error" role="alert" hidden></p>
<a class="calc-cta j2-btn-secondary" href="#register">Register your team</a>
</div>
</div>
<script>
(function(){
  var ticket=document.getElementById('calc-ticket');
  var people=document.getElementById('calc-people');
  var meals=document.getElementById('calc-meals');
  var dateEl=document.getElementById('calc-date');
  var totalEl=document.getElementById('calc-total');
  if(!ticket||!people||!meals||!dateEl||!totalEl){return;}
  var entryEl=document.getElementById('calc-entry');
  var discEl=document.getElementById('calc-discount');
  var mealEl=document.getElementById('calc-mealcost');
  var statusEl=document.getElementById('calc-status');
  var errEl=document.getElementById('calc-error');
  var FEES={Student:400,Professional:800};
  var MEAL=200;
  var CUTOFF='2027-02-15';

  function today(){
    var d=new Date();
    var m=String(d.getMonth()+1);var day=String(d.getDate());
    if(m.length<2){m='0'+m;}
    if(day.length<2){day='0'+day;}
    return d.getFullYear()+'-'+m+'-'+day;
  }
  function rs(n){return 'Rs '+n;}
  function showError(msg){
    if(!errEl){return;}
    if(msg){errEl.textContent=msg;errEl.hidden=false;}
    else{errEl.textContent='';errEl.hidden=true;}
  }

  function update(){
    var p=Number(people.value);
    var m=Number(meals.value);
    var fee=FEES[ticket.value];
    var msg='';
    if(people.value===''||!Number.isInteger(p)||p<1||p>4){
      msg='Enter a number of participants from 1 to 4.';
    }else if(meals.value===''||!Number.isInteger(m)||m<0){
      msg='Enter 0 or more meal passes, as a whole number.';
    }else if(!fee){
      msg='Choose Student or Professional.';
    }
    showError(msg);
    if(msg){
      totalEl.textContent='0';
      if(entryEl){entryEl.textContent=rs(0);}
      if(discEl){discEl.textContent=rs(0);}
      if(mealEl){mealEl.textContent=rs(0);}
      if(statusEl){statusEl.textContent='';}
      return;
    }
    var d=dateEl.value||today();
    var early=d<=CUTOFF;
    var entry=p*fee;
    var discount=early?entry/10:0;
    var mealCost=m*MEAL;
    var total=entry-discount+mealCost;
    totalEl.textContent=String(total);
    if(entryEl){entryEl.textContent=rs(entry);}
    if(discEl){discEl.textContent=discount?'- '+rs(discount):rs(0);}
    if(mealEl){mealEl.textContent=rs(mealCost);}
    if(statusEl){
      statusEl.textContent=early
        ?'Early-bird applies: 10% off entry fees only. Meal passes are not discounted.'
        :'Early-bird ended on 15 February 2027, so full entry fees apply.';
    }
  }

