    for(var i=0;i<ph.length;i++){
      if(ph[i].parentNode&&ph[i].tagName!=='SECTION'){ph[i].parentNode.removeChild(ph[i]);}
    }
  }catch(e){}
  var form=document.getElementById('reg-form');
  if(!form){return;}
  function $(id){return document.getElementById(id);}
  var f={
    team:$('team-name'),lead:$('lead-name'),email:$('lead-email'),phone:$('lead-phone'),
    track:$('reg-track'),ticket:$('reg-ticket'),college:$('college-name'),
    people:$('reg-people'),meals:$('reg-meals'),diet:$('reg-diet')
  };
  var collegeWrap=$('college-wrap'),dietWrap=$('diet-wrap');
  var summary=$('reg-summary'),status=$('reg-status');
  if(!f.team||!f.lead||!f.email||!f.phone||!f.track||!f.ticket||!f.college||!f.people||!f.meals||!f.diet||!collegeWrap||!dietWrap){return;}
  var fields=[f.team,f.lead,f.email,f.phone,f.track,f.ticket,f.college,f.people,f.diet];
  var MIN={'Web Track':1,'AI Track':2,'Hardware Track':2};

  function setError(el,msg){
    var err=$(el.getAttribute('data-error'));
    if(msg){
      if(err){err.textContent=msg;err.hidden=false;}
      el.setAttribute('aria-invalid','true');
    }else{
      if(err){err.textContent='';err.hidden=true;}
      el.removeAttribute('aria-invalid');
    }
  }

  function sync(){
    var isStudent=f.ticket.value==='Student';
    collegeWrap.hidden=!isStudent;
    f.college.disabled=!isStudent;
    f.college.required=isStudent;
    if(isStudent){f.college.setAttribute('aria-required','true');}
    else{f.college.removeAttribute('aria-required');setError(f.college,'');}
