    f.diet.disabled=!wantsMeals;
    f.diet.required=wantsMeals;
    if(wantsMeals){f.diet.setAttribute('aria-required','true');}
    else{f.diet.removeAttribute('aria-required');setError(f.diet,'');}
  }

  function msgFor(el){
    var v=(el.value||'').trim();
    if(el===f.team){return v?'':'Enter your team name.';}
    if(el===f.lead){return v?'':'Enter the team lead\u2019s name.';}
    if(el===f.email){
      if(!v){return 'Enter the lead\u2019s email address.';}
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)?'':'Enter a valid email address, like name@example.com.';
    }
    if(el===f.phone){
      if(!v){return 'Enter the lead\u2019s phone number.';}
      var digits=v.replace(/[\s\-()]/g,'');
      return /^\+?\d{7,15}$/.test(digits)?'':'Enter a valid phone number: digits only, with an optional + at the start.';
    }
    if(el===f.track){return v?'':'Choose a track.';}
    if(el===f.ticket){return v?'':'Choose Student or Professional.';}
    if(el===f.college){
      if(f.ticket.value!=='Student'){return '';}
      return v?'':'Enter your college name. It is required for Student tickets.';
    }
    if(el===f.people){
      var n=Number(v);
