    el.addEventListener('input',handler);
    el.addEventListener('change',handler);
  });
  [f.ticket,f.meals].forEach(function(el){
    el.addEventListener('input',sync);
    el.addEventListener('change',sync);
  });

  form.addEventListener('submit',function(e){
    sync();
    var first=null,count=0;
    fields.forEach(function(el){
      var m=el.disabled?'':msgFor(el);
      setError(el,m);
      if(m){count++;if(!first){first=el;}}
    });
    if(count){
      e.preventDefault();
      if(status){status.hidden=true;}
      if(summary){
        summary.textContent=count===1?'Please fix the 1 field marked below, then send again.':'Please fix the '+count+' fields marked below, then send again.';
        summary.hidden=false;
      }
      try{first.focus();}catch(err){}
      return;
    }
    if(summary){summary.hidden=true;}
    if(status){
      status.textContent='Opening your email app with your registration for register@example.com. Press send there to finish. If nothing opens, email your details to register@example.com.';
      status.hidden=false;
    }
  });

  sync();
})();
</script>
