<script>
(function(){
  var dEl=document.getElementById('cd-days');
  var hEl=document.getElementById('cd-hours');
  var mEl=document.getElementById('cd-minutes');
  var sEl=document.getElementById('cd-seconds');
  var statusEl=document.getElementById('cd-status');
  if(!dEl||!hEl||!mEl||!sEl){return;}
  var TARGET=new Date('2027-03-06T10:00:00+05:30').getTime();
  var timer=null;
  function pad(n){return n<10?'0'+n:String(n);}
  function render(){
    var diff=TARGET-Date.now();
    if(isNaN(diff)||diff<=0){
      dEl.textContent='00';hEl.textContent='00';mEl.textContent='00';sEl.textContent='00';
      if(statusEl){
        statusEl.textContent='CodeSprint Pune 2027 has started.';
        statusEl.hidden=false;
      }
      if(timer){clearInterval(timer);timer=null;}
      return;
    }
    var total=Math.floor(diff/1000);
    var days=Math.floor(total/86400);
    var hours=Math.floor((total%86400)/3600);
    var minutes=Math.floor((total%3600)/60);
    var seconds=total%60;
    dEl.textContent=pad(days);
    hEl.textContent=pad(hours);
    mEl.textContent=pad(minutes);
    sEl.textContent=pad(seconds);
    if(statusEl){statusEl.hidden=true;}
  }
  render();
  timer=setInterval(render,1000);
})();
</script>
</section>
