<script>
(function(){
  var nav=document.getElementById('site-nav');
  if(!nav){return;}
  var links=[].slice.call(nav.querySelectorAll('a.nav-link'));
  if(!links.length){return;}
  var current=null;
  var queued=false;

  function targetFor(a){
    var h=a.getAttribute('href')||'';
    if(h.charAt(0)!=='#'||h.length<2){return null;}
    var id=h.slice(1);
    return document.querySelector('section[id="'+id+'"]')||document.getElementById(id);
  }

  function centerInNav(a){
    if(nav.scrollWidth<=nav.clientWidth){return;}
    var n=nav.getBoundingClientRect();
    var r=a.getBoundingClientRect();
    nav.scrollLeft+=r.left-n.left-(nav.clientWidth-r.width)/2;
  }

  function setActive(a){
    if(a===current){return;}
    links.forEach(function(l){
      if(l===a){l.classList.add('active');l.setAttribute('aria-current','true');}
      else{l.classList.remove('active');l.removeAttribute('aria-current');}
    });
    current=a;
    if(a){centerInNav(a);}
  }

  function update(){
    queued=false;
    var line=nav.offsetHeight+48;
    var best=null,bestTop=-Infinity;
    var lowest=null,lowestTop=-Infinity;
    links.forEach(function(a){
      var t=targetFor(a);
      if(!t){return;}
      var top=t.getBoundingClientRect().top;
      if(top<=line&&top>bestTop){best=a;bestTop=top;}
      if(top>lowestTop){lowest=a;lowestTop=top;}
    });
    var doc=document.documentElement;
    var atBottom=window.innerHeight+(window.pageYOffset||doc.scrollTop||0)>=doc.scrollHeight-2;
    if(atBottom&&lowest&&lowestTop<window.innerHeight*0.75){best=lowest;}
    if(!best){best=links[0];}
    setActive(best);
  }

  function queue(){
    if(queued){return;}
    queued=true;
    if(window.requestAnimationFrame){window.requestAnimationFrame(update);}
    else{setTimeout(update,16);}
  }

  links.forEach(function(a){
    a.addEventListener('click',function(e){
      var h=a.getAttribute('href')||'';
      var t=targetFor(a);
      if(t&&h.charAt(0)==='#'&&t!==document.getElementById(h.slice(1))){
        e.preventDefault();
        t.scrollIntoView();
        try{history.replaceState(null,'',h);}catch(err){}
      }
    });
  });

  window.addEventListener('scroll',queue,{passive:true});
  window.addEventListener('resize',queue);
  window.addEventListener('load',queue);
  window.addEventListener('hashchange',queue);
  update();
  setTimeout(update,300);
})();
</script>
