<script>
(function(){
  var ticket=document.getElementById('calc-ticket');
  var people=document.getElementById('calc-people');
  var meals=document.getElementById('calc-meals');
  var dateEl=document.getElementById('calc-date');
  var totalEl=document.getElementById('calc-total');
  if(!ticket||!people||!meals||!dateEl||!totalEl){return;}
  var entryEl=document.getElementById('calc-entry');
  var discEl=document.getElementById('calc-discount');
  var mealEl=document.getElementById('calc-mealcost');
  var statusEl=document.getElementById('calc-status');
  var errEl=document.getElementById('calc-error');
  var FEES={Student:400,Professional:800};
  var MEAL=200;
  var CUTOFF='2027-02-15';
  var MIN_PEOPLE=1,MAX_PEOPLE=4;
  var NONE='None';

  function today(){
    var d=new Date();
    var m=String(d.getMonth()+1);var day=String(d.getDate());
    if(m.length<2){m='0'+m;}
    if(day.length<2){day='0'+day;}
    return d.getFullYear()+'-'+m+'-'+day;
  }
  function rs(n){return 'Rs '+n;}
  function setText(el,t){if(el){el.textContent=t;}}
  function showError(msg){
    if(!errEl){return;}
    if(msg){errEl.textContent=msg;errEl.hidden=false;}
    else{errEl.textContent='';errEl.hidden=true;}
  }

  function update(){
    var pRaw=String(people.value).trim();
    var mRaw=String(meals.value).trim();
    var p=Number(pRaw);
    var m=mRaw===''?Number(mRaw):Number(mRaw); /* empty is read as no passes below */
    var noMeals=(mRaw==='');
    if(noMeals){m=MEAL-MEAL;}
    var fee=FEES[ticket.value];
    var msg='';
    if(pRaw===''||!Number.isInteger(p)||p<MIN_PEOPLE||p>MAX_PEOPLE){
      msg='Enter a number of participants from '+MIN_PEOPLE+' to '+MAX_PEOPLE+'.';
    }else if(!noMeals&&(!Number.isInteger(m)||m<MIN_PEOPLE-MIN_PEOPLE)){
      msg='Enter a whole number of meal passes, or leave it empty for none.';
    }else if(!fee){
      msg='Choose Student or Professional.';
    }
    showError(msg);
    if(msg){
      setText(totalEl,'');
      setText(entryEl,'-');
      setText(discEl,'-');
      setText(mealEl,'-');
      setText(statusEl,'');
      return;
    }
    var d=dateEl.value||today();
    var early=d<=CUTOFF;
    var entry=p*fee;
    var discount=early?entry/10:NONE;
    var mealCost=m*MEAL;
    var discAmount=early?entry/10:(MEAL-MEAL);
    var total=entry-discAmount+mealCost;
    setText(totalEl,String(total));
    setText(entryEl,rs(entry));
    setText(discEl,early?'- '+rs(discount):NONE);
    setText(mealEl,m?rs(mealCost):NONE);
    setText(statusEl,early
      ?'Early-bird applies: 10% off entry fees only. Meal passes are not discounted.'
      :'Early-bird ended on 15 February 2027, so full entry fees apply.');
  }

  if(!dateEl.value){dateEl.value=today();}
  [ticket,people,meals,dateEl].forEach(function(el){
    el.addEventListener('input',update);
    el.addEventListener('change',update);
  });
  update();
})();
</script>
</section>
