/* High-contrast mode: toggled by class "hc" on body */
body.hc{--j2-background:#000;--j2-surface:#000;--j2-text:#fff;--j2-muted:#fff;--j2-primary:#FFFF00;--j2-accent:#FFFF00;--j2-secondary:#fff}
