/* Errors stay distinct from headings and links */
body.hc section[id] [id$="-error"],body.hc section[id] .reg-error,body.hc section[id] .reg-summary,body.hc section[id] .field-error,body.hc section[id] .error{color:#FFB3B3!important;font-weight:700}
