</style>
<button type="button" id="contrast-toggle" class="j2-btn-secondary" aria-pressed="false">High contrast: off</button>
<script>
(function(){
  var btn=document.getElementById('contrast-toggle');
  if(!btn||!document.body){return;}
  var bar=document.getElementById('contrast-bar');
  var hero=document.getElementById('hero');
  /* Keep the strip in normal flow at the top of the page, just below the fixed nav
     (body already has top padding for the nav). */
  if(bar&&hero&&hero.parentNode){hero.parentNode.insertBefore(bar,hero);}
  var KEY='j2-high-contrast';
  function apply(on){
    document.body.classList.toggle('hc',on);
    btn.setAttribute('aria-pressed',on?'true':'false');
    btn.textContent=on?'High contrast: on':'High contrast: off';
  }
  var saved=false;
  try{saved=window.localStorage.getItem(KEY)==='1';}catch(e){}
  apply(saved);
  btn.addEventListener('click',function(){
    var on=!document.body.classList.contains('hc');
    apply(on);
    try{window.localStorage.setItem(KEY,on?'1':'0');}catch(e){}
  });
})();
</script>
</div>
